<style>
.cfp-list [data-file-row]{cursor:pointer}.cfp-list [data-file-row]:focus-visible{outline:2px solid #6577df;outline-offset:-2px}
.cfw .cfw-actions [data-cf-money]{display:none!important}
.cfw .cfw-actions [data-cf-cancel]{grid-column:auto;width:24px;height:24px;padding:0;display:inline-flex;align-items:center;justify-content:center;font-size:10px;color:#d43b51;border-color:#f4cbd2;background:#fff6f7}.cfw .cfw-actions [data-cf-cancel] .cfmoney-cancel-label{display:none}.cfw .cfw-actions [data-file-print]{color:#1376df;background:#f0f8ff;border-color:#c9e3fc}
.cfw .cfw-actions .cfw-delete{color:#dc354e;border-color:#f4cbd2;background:#fff6f7}
.cfw .cfw-party-cell{min-width:190px;max-width:280px}.cfw .cfw-party-name{font-weight:400;color:#253b62}.cfw .cfw-party-name i{color:#6678df;font-size:10px;margin-right:4px}.cfw .cfw-provider-line{display:flex;align-items:center;gap:5px;font-size:10px;line-height:1.7;color:#52617a}.cfw .cfw-provider-line>i{color:#a3afc3;font-size:9px}.cfw .cfw-provider-line>span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;min-width:0}.cfw .cfw-provider-line>a{flex-shrink:0;font-size:9px;color:#8799d7}.cfw .cfw-provider-more summary{cursor:pointer;color:#8391ac;font-size:10px}.cfw .cfw-provider-more summary:hover{color:#3156c8}
.cfw .cfw-party-link{color:#3156c8;text-decoration:none;display:inline-block;border-radius:3px}.cfw .cfw-party-link i{font-size:9px;color:#8190ae;margin-right:3px}.cfw .cfw-party-link:hover{color:#1743b5;text-decoration:underline}.cfw .cfw-party-link:focus-visible{outline:2px solid #3156c8;outline-offset:3px}.cfw small .cfw-party-link{font-size:10px}
.cfp-heading{box-shadow:0 2px 3px #18243b10}.cfp-heading-text{flex:1}.cfp-heading-icon{display:flex;align-items:center;justify-content:center;width:42px;height:42px;background:#fff6ef;color:#f65b22;border-radius:8px}.cfp-kpis{display:grid;grid-template-columns:repeat(8,minmax(0,1fr));gap:8px;margin-bottom:14px}.cfp-kpi{padding:9px 10px;border-radius:9px;background:var(--cfp-bg);color:var(--cfp-color)}.cfp-kpi>div{display:flex;align-items:center;gap:8px;margin-bottom:4px}.cfp-kpi-icon{display:flex;align-items:center;justify-content:center;width:27px;height:27px;border-radius:7px;background:var(--cfp-color);color:white}.cfp-kpi strong{font-size:20px;line-height:1}.cfp-kpi>b{display:block;text-transform:uppercase;font-size:9px}.cfp-kpi small{display:block;font-size:9px;margin-top:4px;line-height:1.4}.cfp-kpi.indigo{--cfp-bg:#e8edff;--cfp-color:#4f46df}.cfp-kpi.amber{--cfp-bg:#fff4d9;--cfp-color:#df901d}.cfp-kpi.emerald{--cfp-bg:#ddfaee;--cfp-color:#0caa7d}.cfp-kpi.rose{--cfp-bg:#ffe8ee;--cfp-color:#dd2259}.cfp-kpi.red{--cfp-bg:#ffe7e9;--cfp-color:#ec4256}.cfp-kpi.slate{--cfp-bg:#e9eef4;--cfp-color:#61758d}.cfp-kpi.sky{--cfp-bg:#e2f5ff;--cfp-color:#159dcb}.cfp-kpi.violet{--cfp-bg:#efebff;--cfp-color:#8258e8}@media(max-width:1200px){.cfp-kpis{grid-template-columns:repeat(4,minmax(0,1fr))}}@media(max-width:600px){.cfp-kpis{grid-template-columns:repeat(2,minmax(0,1fr))}}@media print{.cfp-kpis{display:none}}
.cfl-titlebar{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:16px 0 12px}.cfl-title{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.cfl-title h1{font-size:14px;font-weight:800;margin:0}.cfl-title small{color:#8290a7;font-size:10px}.cfl-summary{display:grid;grid-template-columns:minmax(240px,1fr) minmax(160px,260px) 150px 190px;gap:20px;align-items:center}.cfl-identity{display:flex;gap:16px;align-items:center}.cfl-avatar{font-size:25px}.cfl-identity p{font-size:11px;margin:4px 0}.cfl-identity small,.cfl-meta small{font-size:9px;display:block;letter-spacing:.4px}.cfl-meta{border-left:1px solid #ffffff26;padding-left:16px}.cfl-meta b{display:block;font-size:12px;margin:4px 0 10px;overflow-wrap:anywhere}.cfl-buttons{display:grid;grid-template-columns:1fr 1fr;gap:6px}.cfl-buttons .cfw-btn{justify-content:center;padding:7px 8px}.cfl-banner{margin-bottom:14px}@media(max-width:1050px){.cfl-summary{grid-template-columns:1fr 1fr}.cfl-titlebar{flex-wrap:wrap}}@media(max-width:600px){.cfl-summary{grid-template-columns:1fr}.cfl-meta{border-left:0;padding-left:0}}@media print{.cfl-titlebar{display:none}}
.cfw{color:#18243b;font-size:12px}.cfw-panel{background:#fff;border:1px solid #dce3f0;border-radius:12px;overflow:hidden;margin-bottom:14px}.cfw-head{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:18px}.cfw-head h1{font-size:17px;font-weight:800;margin:0}.cfw-head p{color:#8190a9;font-size:11px;margin:4px 0 0}.cfw-btn{display:inline-flex;align-items:center;gap:6px;padding:8px 12px;border:1px solid #dce3f0;border-radius:7px;background:white;color:#2563eb;font-size:11px}.cfw-banner{background:linear-gradient(115deg,#3448c3,#7251d7);padding:22px;color:#fff;border-radius:14px;margin-bottom:16px;box-shadow:0 8px 14px #4053ba24}.cfw-banner h2{font-size:19px;font-weight:800}.cfw-metrics{display:grid;grid-template-columns:repeat(6,1fr);gap:1px;background:#f6f8ff;color:#1c2b50;border-radius:10px;margin-top:16px;padding:12px}.cfw-metric{padding:0 12px;border-right:1px solid #d7def7}.cfw-metric:last-child{border:0}.cfw-metric small{display:block;font-size:9px;font-weight:700;text-transform:uppercase;color:#5360b7}.cfw-metric strong{display:block;font-size:17px;margin-top:3px}.cfw-groups{display:flex;gap:10px;overflow:auto;margin:14px 0}.cfw-group{flex:0 0 220px;background:white;border:1px solid #d8def0;border-left:4px solid #7a66df;border-radius:12px;padding:13px;box-shadow:0 3px 6px #1b2d4c0b}.cfw-group strong{display:block;color:#3856c8}.cfw-group small{display:block;color:#8a95a8;margin-top:5px}.cfw-filter{display:flex;align-items:center;gap:8px;flex-wrap:wrap;padding:12px;background:#f9faff;border-bottom:1px solid #e0e6f2}.cfw-filter input,.cfw-filter select{border:1px solid #dce3f0;border-radius:7px;padding:7px;background:white;font-size:11px}.cfw-filter input[type=search]{flex:1;min-width:220px}.cfw-table{width:100%;border-collapse:collapse;min-width:1060px}.cfw-table th{background:#edf2ff;color:#244bdd;text-transform:uppercase;letter-spacing:.35px;font-size:9px;padding:12px;text-align:left}.cfw-table td{padding:13px 12px;vertical-align:top;border-top:1px solid #dae2f3;font-size:11px}.cfw-table td small{display:block;font-size:10px;color:#8c98ae;line-height:1.7}.cfw-name{font-weight:800;text-transform:uppercase}.cfw-blue{color:#6254e8}.cfw-red{color:#e33459}.cfw-green{color:#0ba777}.cfw-tag{display:inline-block;background:#eef2ff;color:#3156d8;border-radius:6px;padding:3px 7px;font-size:9px;margin:2px 0}.cfw-tag.warn{background:#fff0f3;color:#e02c51}.cfw-actions{display:grid;grid-template-columns:24px 24px;gap:5px}.cfw-actions a,.cfw-actions button{width:24px;height:24px;border:1px solid #d5def3;border-radius:5px;display:flex;align-items:center;justify-content:center;color:#3863d7;background:#fff;font-size:10px}.cfw-journey-cell{padding:0!important;background:#f6f8ff}.cfw-journey{display:flex;min-width:1100px;padding:18px 15px 15px}.cfw-step{position:relative;flex:1;display:flex;flex-direction:column;align-items:center;text-align:center;color:#8290a7}.cfw-step:before{content:'';position:absolute;height:2px;background:#dce4f2;left:-50%;right:50%;top:12px}.cfw-step:first-child:before{display:none}.cfw-step.done:before{background:#39c76a}.cfw-dot{z-index:1;width:25px;height:25px;border:1px solid #cbd7e9;border-radius:50%;background:white;display:flex;align-items:center;justify-content:center;font-size:9px}.cfw-step.done .cfw-dot{color:#16a34a;border-color:#40c676;background:#e3faea}.cfw-step.current .cfw-dot{background:#4459de;color:white;border-color:#4459de;box-shadow:0 0 0 5px #e2e7ff}.cfw-step b{font-size:8px;margin-top:8px;max-width:82px}.cfw-step small{font-size:7px;margin-top:3px}.cfw-step.current b{color:#3143bc}.cfw-empty{text-align:center;padding:35px;color:#8490a8}@media(max-width:800px){.cfw-metrics{grid-template-columns:repeat(3,1fr);gap:12px}.cfw-head{flex-wrap:wrap}.cfw-banner{padding:16px}}@media print{.cfw-filter,.cfw-actions,.cfw-groups,.cff-toolbar,.cfw-btn{display:none!important}.cfw-panel{overflow:visible}.cfw-table{min-width:0}.cfw-journey{min-width:0}}
</style>
<style>
.cfw-group-detail{min-height:69px;padding:5px 0;margin-bottom:5px;border-bottom:1px dashed #e3e8f2}.cfw-group-detail:last-child{border-bottom:0;margin-bottom:0}.cfw-table tr[role=link]:hover td{background:#f0f4ff}.cfw-table tr[role=link]:focus{outline:2px solid #4563de;outline-offset:-2px}
</style>
